class Counter {
    static int count = 0;
    int id;

    Counter() {
        count++;
        id = count;
    }
}

Counter c1 = new Counter();
Counter c2 = new Counter();

System.out.println(c1.id);
System.out.println(c2.id);
System.out.println(Counter.count);
System.out.println(c1.count == c2.count);
